var Tesseract = {
    recognize: function (imageFile, lang, options) {
        const logger = (options && options.logger) || function () {};
        const file = (imageFile instanceof FileList) ? imageFile[0] : imageFile;

        return new Promise((resolve, reject) => {
            if (!file) {
                return reject(new Error("No image file provided."));
            }
            if (file.size > 1024 * 1024) {
                return reject(new Error("Image size exceeds 1 MB (free API limit)."));
            }

            logger({ status: 'loading ocr engine', progress: 0.1 });

            const formData = new FormData();
            formData.append('file', file);
            formData.append('language', lang || 'eng');
            formData.append('isOverlayRequired', 'false');
            formData.append('apikey', 'K81812820288957');

            logger({ status: 'recognizing text', progress: 0.6 });

            fetch('https://api.ocr.space/parse/image', {
                method: 'POST',
                body: formData
            })
            .then(response => {
                if (!response.ok) {
                    throw new Error("Server response is not okay (" + response.status + ")");
                }
                return response.json();
            })
            .then(json => {
                if (json.IsErroredOnProcessing) {
                    const pesan = Array.isArray(json.ErrorMessage)
                        ? json.ErrorMessage.join(', ')
                        : (json.ErrorMessage || "Failed to process the image");
                    throw new Error(pesan);
                }

                const teks = (json.ParsedResults || [])
                    .map(r => r.ParsedText || "")
                    .join("\n");

                logger({ status: 'recognizing text', progress: 1 });
                resolve({ data: { text: teks } });
            })
            .catch(err => {
                console.error("Fetch error:", err);
                reject(err);
            });
        });
    }
};